async function purchase(action){if(busy)return;shopMessage=action.type==='buy'?'ACQUIRING '+VEHICLES[selectedVehicle].name+'…':action.type==='tune'?'ALLOCATING BUILD POINTS…':'PURCHASING '+UPGRADES[action.choice].name+'…';busy=true;renderMenu();try{await command(action);status('');shopMessage=action.type==='buy'?VEHICLES[selectedVehicle].name+' ACQUIRED / READY TO RACE':action.type==='tune'?'BUILD SAVED / '+action.levels.reduce((a,b)=>a+b,0)+' OF '+BUILD_BUDGET+' POINTS':UPGRADES[action.choice].name+' OWNED / TIER '+g.career.upgrades[selectedVehicle][action.choice];audio.unlock();audio.play('collect');announce(shopMessage);}catch(e){shopMessage=e.message;status(e.message);}finally{busy=false;renderMenu();}}
async function start(){closePlan();if(busy||document.hidden||document.documentElement.dataset.orientationBlocked==='true')return;if(!eventAvailable(selectedMode)){status('Win three contracts in the previous chapter to unlock.');setView('career');return;}if(!(g.career.owned&(1<<selectedVehicle))){setView('garage');return;}audio.unlock();busy=true;renderMenu();try{await command({type:'race',mode:selectedMode,vehicle:selectedVehicle,gadget,difficulty});renderer.reset();await resume();}catch(e){status(e.message);}finally{busy=false;if(view!=='race')renderMenu();}}
async function startSpec(){if(busy||document.hidden||document.documentElement.dataset.orientationBlocked==='true')return;audio.unlock();busy=true;try{await command({type:'race',mode:0,vehicle:0,gadget:0,difficulty:0,spec:1});selectedMode=selectedVehicle=gadget=difficulty=0;renderer.reset();await resume();}catch(e){status(e.message);}finally{busy=false;}}
let resumeEpoch=0;
async function resume(){const epoch=++resumeEpoch;if(!loaded)return void boot();if(g.over){setView('result');return;}if(document.hidden||document.documentElement.dataset.orientationBlocked==='true')return;audio.unlock();await saveAll();status('Preparing car and circuit…');await renderer.prepareRace(g);status('');if(epoch!==resumeEpoch||document.hidden||document.documentElement.dataset.orientationBlocked==='true'){clear();setView('pause');return;}if(!g.tick){lastRecoveryId=null;blockedMs=0;roadblockCueId=null;roadblockCueStage=-1;}clear();audio.unlock();ghost.begin(g,confirmed?.session.id);running=false;countdown=1800;accumulator=0;setView('race');hidden($('#countdown'),false);setText('countdown','3');canvas.focus();}
