async function leaveStore(){if(busy||ending)return;busy=true;menuSystem.syncNav(view);try{await pause();await saveAll();window.top.location.assign(new URL('/',location.href).href);}catch{busy=false;status('Could not save. Reconnect before returning to UTXOPlay.');renderMenu();}}
async function finish(){ghost.persist(g);if(ending)return;running=false;clear();busy=true;ending=true;const wreck=g.finish_reason===2&&!motion.matches;renderer.coastTime=renderer.coastDistance=0;
 hidden(actions,true);hidden(stick,true);hidden(pauseButton,true);status('Saving race rewards…');if(g.spec){const finished=structuredClone(g),finishedGhost=ghost,capture=finishedGhost.capture;void saveAll().then(()=>api('replay',{})).then(r=>{if(finishedGhost.complete(finished,r.verified,capture))toast('PERSONAL GHOST SAVED');}).catch(()=>{});}
 try{await Promise.all([saveAll(),new Promise(resolve=>setTimeout(resolve,motion.matches?0:wreck?1700:1100))]);g=structuredClone(confirmed.game);previous=structuredClone(g);status('');}catch{}finally{ending=false;busy=false;setView(g.over?'result':'pause');}}

