function effects(before,after){
 if(after.physics_version>=13){for(const ev of after.events){if(ev.kind==='rival-launch'){toast('COURIER ON THE MOVE');renderer.event({type:'rival-launch',id:ev.actor},after,before);audio.play('start');}else if(ev.kind==='chapter-clear')toast('CHAPTER COMPLETE / +750 CR');else if(ev.kind==='sector-clear')toast('SECTOR CONTRACT / +75 CR AT THE FINISH');else if(ev.kind==='finale')toast('FINAL CLEAN EXIT BANKED');}}
 if(after.physics_version>=11){if(after.events.some(e=>e.kind==='clean-exit'))toast('CLEAN EXIT · CHARGE +35');else if(Math.floor(after.charge/300)>Math.floor(before.charge/300))toast(after.drifting?'DRIFT · BOOST READY':after.draft_ticks>=12?'DRAFT · BOOST READY':after.near_misses>before.near_misses?'CLOSE PASS · BOOST READY':'BOOST READY');if(EVENTS[after.mode].type===2&&sectorIndex(after)!==sectorIndex(before))toast('SECTOR '+(sectorIndex(after)+1)+' · CONTROL YOUR DRIFT');}

 for(const cue of audio.feedback(before,after))if(cue.type==='ready'&&!motion.matches)$('#charge').children[cue.tier-1]?.animate([{filter:'brightness(2.1)'},{filter:'brightness(1)'}],{duration:320});
 for(const e of combatFeedback(before,after)){
  const player=e.target===-1;
  if(e.kind==='scrape'){renderer.event({type:'scrape'},after,before);}
  else if(e.kind==='collision'||e.kind==='wreck'||e.kind==='shield-break'){renderer.event({type:e.kind},after,before);if(e.kind!=='shield-break')audio.play('damage',after);if(e.kind==='wreck')toast('WRECKED');}
  else if(e.kind==='hit'||e.kind==='disable'||e.kind==='block'){renderer.event({type:player?'hit':e.kind==='block'?'rival-block':e.kind==='disable'?'disable':'rival-hit',id:player?-1:e.target},after,before);if(player){audio.play('damage',after);toast(e.kind==='disable'?'SYSTEMS DISABLED / RECOVERING':'SYSTEM HIT');}else if(e.kind==='disable'&&e.actor===-1){audio.play('enemy');toast('RIVAL DISABLED');}}
  else if(e.kind==='shot'){renderer.event({type:e.actor===-1?'pulse':'rival-shot',id:e.actor,target:e.target},after,before);if(e.actor===-1)audio.play('pulse');}
  else if(e.kind==='guard'&&e.actor===-1){renderer.event({type:'guard'},after,before);audio.play('guard');}
  else if(e.kind==='counter'){renderer.event({type:'counter'},after,before);audio.play('counter');toast('JAMMED / CHARGE +100');}
  else if(e.kind==='dodge')toast('EVADED / CHARGE +60');
  else if(e.kind==='contract')toast('TARGET SECURED / '+combatHud(after).completed+' OF '+EVENTS[after.mode].rivals);
  else if(e.kind==='recover'){renderer.event({type:'recover',id:player?-1:e.target},after,before);if(player){toast('SYSTEMS ONLINE');audio.play('guard');}}
 }
 if(after.checkpoint>before.checkpoint){toast(after.physics_version>=13&&after.sector_marks[before.checkpoint]?'RELAY / EQUIPMENT RESTORED · SECTOR +75 CR AT FINISH':'RELAY / EQUIPMENT RESTORED');renderer.event({type:'wave'},after,before);}
 if(after.physics_version>=13&&after.events.some(e=>e.kind==='finale'))toast('FINAL CLEAN EXIT BANKED');
 if(after.over&&!before.over&&after.won)audio.play('wave');
}

